import { execFile } from 'node:child_process'
import { createHash } from 'node:crypto'
import { mkdir, readFile } from 'node:fs/promises'
import { createRequire } from 'node:module'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { promisify } from 'node:util'

// Prepared archives are generated by scripts/prepare-luaskills-unix.mjs.
// 预处理归档由 scripts/prepare-luaskills-unix.mjs 生成。
const TARGETS = new Set(['linux-arm64', 'linux-x64', 'macos-arm64', 'macos-x64'])

// Extract with the platform tar already required by the SDK installer.
// 使用 SDK 安装流程已要求的系统 tar 解压。
const untar = promisify(execFile)

/** Map Node's platform and architecture to the prepared archive name.
 * 将 Node 的平台和架构映射到预处理归档名称。 */
export function preparedUnixTarget(platform = process.platform, arch = process.arch): string | undefined {
  if (platform !== 'darwin' && platform !== 'linux') return undefined
  const target = `${platform === 'darwin' ? 'macos' : 'linux'}-${arch}`
  if (!TARGETS.has(target)) throw new Error(`LuaSkills does not provide a prepared runtime for ${target}.`)
  return target
}

/** Copy the exact verified runtime archive into the new slot by extracting only the named asset.
 * 仅解压指定并校验过的运行包，将其安装到候选版本目录。 */
export async function installPreparedUnixRuntime(target: string, runtimeRoot: string, contract: string): Promise<void> {
  const archive = fileURLToPath(new URL(`../assets/native/${target}.tar.gz`, import.meta.url))
  // The archive and its checksum are shipped together in the integrity-checked plugin package.
  // 归档和摘要一起随通过完整性校验的插件包分发。
  const checksum = (await readFile(`${archive}.sha256`, 'utf8')).trim()
  const archiveBytes = await readFile(archive)
  if (createHash('sha256').update(archiveBytes).digest('hex') !== checksum) {
    throw new Error(`The prepared LuaSkills archive for ${target} failed SHA-256 verification.`)
  }
  await mkdir(runtimeRoot, { recursive: true })
  await untar('tar', ['-xzf', archive, '-C', runtimeRoot])
  // The static core must implement the exact same contract as the installed SDK.
  // 静态核心必须实现与已安装 SDK 完全一致的契约。
  const sidecar = await readFile(path.join(runtimeRoot, 'resources', 'dsh-ffi-contract.sha256'), 'utf8')
  const fields = sidecar.trim().split(/\s+/)
  if (fields.length !== 2 || fields[0] !== contract || fields[1] !== 'contract.json') {
    throw new Error('The prepared LuaSkills core does not match the installed SDK contract.')
  }
}

/** Load the exact engine library globally so native Lua modules bind to the VM that created their state.
 * 全局加载引擎动态库，让原生 Lua 模块绑定到创建其状态的同一个 VM。 */
export function openUnixLuaSymbols(libraryPath: string, sdkUrl: string): { unload(): void } {
  // Koffi otherwise opens libraries with RTLD_LOCAL, which hides Lua symbols from later require() calls.
  // Koffi 默认使用 RTLD_LOCAL，会隐藏后续 require() 所需的 Lua 符号。
  const load: (file: string, flags: { global: boolean }) => { unload(): void } = createRequire(sdkUrl)('koffi').load
  return load(libraryPath, { global: true })
}

// Run in the installed engine, exercising symbols, loader paths, random bytes, AES-GCM and libcurl.
// 在已安装引擎中实际验证符号、加载路径、随机数、AES-GCM 和 libcurl。
export const UNIX_NATIVE_SMOKE = `
local random = require("openssl.rand")
local cipher = require("openssl.cipher")
local curl = require("lcurl.safe")
local lfs = require("lfs")
local handle = assert(curl.easy({url = "https://example.com/", ssl_verifypeer = true, ssl_verifyhost = true}))
handle:close()
local aes = assert(cipher.new("aes-256-gcm"))
assert(aes:encrypt(string.rep("k", 32), string.rep("i", 12)))
assert(aes:update("luaskills"))
assert(aes:final())
assert(#aes:getTag(16) == 16)
return #random.bytes(32) == 32 and type(lfs.currentdir()) == "string"
`
